return typeof(UnityEditor.AssetPackage.Package).GetMethods().Where(m=>m.Name=="Export").Select(m=>new{signature=m.ToString(),parameters=m.GetParameters().Select(p=>new{type=p.ParameterType.FullName,fields=p.ParameterType.GetFields().Select(f=>f.Name+":"+f.FieldType.Name).ToArray(),properties=p.ParameterType.GetProperties().Select(f=>f.Name+":"+f.PropertyType.Name).ToArray()}).ToArray()}).ToArray();
